// Devourer of Knowledge / Пожиратель Знаний (Дар Тзинча, wdbc-1rno) —
// «воспоминание» (нарративная половина) НЕ реализовано. Навык — на СУТКИ
// (worldTime), 9 дней подряд у ТОЙ ЖЕ пары «жертва+Навык» — навсегда.
// «9 минут» касания книги не считаются (Состязания/техники в этой системе
// тоже не списывают ОД программно — тот же честный предел, что у Танца
// Обмана, wdbc-1rno).
const targetDoc = game.user.targets?.first?.() ?? [...(game.user.targets ?? [])][0];
const targetActor = targetDoc?.actor ?? null;
if (!targetActor) {
  ui.notifications?.warn("Пожиратель Знаний: выберите одну цель.");
} else {
  const skillEntries = Object.entries(targetActor.system?.skills ?? {})
    .filter(([, s]) => s?.rank && s.rank !== "untrained");
  if (!skillEntries.length) {
    ui.notifications?.warn(`Пожиратель Знаний: у ${targetActor.name} нет ни одного изученного Навыка.`);
  } else {
    const options = skillEntries.map(([key, s]) => `<option value="${key}">${key} (${s.rank})</option>`).join("");
    new Dialog({
      title: "Пожиратель Знаний",
      content: `<div style="padding:6px;">
        <div class="roll-threshold">Навык, который ${actor.name} заберёт у ${targetActor.name} на сутки (или навсегда — 9-й день подряд):</div>
        <select id="dok-skill" style="width:100%;margin-top:4px;">${options}</select>
      </div>`,
      buttons: {
        go: {
          icon: '<i class="fas fa-brain"></i>', label: "Пожрать",
          callback: async html => {
            const skillKey = html.find("#dok-skill").val();
            const worldTime = game.time?.worldTime ?? 0;
            const DAY = 86400;
            const today = Math.floor(worldTime / DAY);
            const listFlag = "devourerOfKnowledgeThefts";
            const list = actor.getFlag("warhammer-dbc", listFlag) ?? [];
            const recKey = `${targetActor.uuid}|${skillKey}`;
            const prev = list.find(r => r.key === recKey);
            let streak, sameDayRepeat = false;
            if (prev && prev.lastDay === today) { streak = prev.streak; sameDayRepeat = true; }
            else if (prev && prev.lastDay === today - 1) { streak = prev.streak + 1; }
            else { streak = 1; }

            if (sameDayRepeat) {
              ui.notifications?.info(`Пожиратель Знаний: этот Навык у ${targetActor.name} уже пожирался сегодня (серия ${streak}/9).`);
              return;
            }

            if (streak >= 9) {
              // Перманентная кража — жертва теряет НАВСЕГДА, носитель получает
              // Ступень, которая была у жертвы на момент последней временной
              // кражи (та же Ступень все 9 дней держалась).
              const finalRank = targetActor.system.skills[skillKey]?.rank || prev?.victimPrevRank || "untrained";
              await targetActor.update({ [`system.skills.${skillKey}.rank`]: "untrained" });
              await actor.update({ [`system.skills.${skillKey}.rank`]: finalRank });
              const permFlag = "devourerOfKnowledgePermanent";
              const perm = actor.getFlag("warhammer-dbc", permFlag) ?? [];
              if (!perm.includes(skillKey)) await actor.setFlag("warhammer-dbc", permFlag, [...perm, skillKey]);
              await actor.setFlag("warhammer-dbc", listFlag, list.filter(r => r.key !== recKey));
              await ChatMessage.create(ChatMessage.applyRollMode({
                speaker,
                content: `<div class="wh-roll-result">
                  <div class="roll-header">Пожиратель Знаний — ${actor.name}</div>
                  <div class="roll-threshold">9 дней подряд — ${targetActor.name} НАВСЕГДА теряет Навык «${skillKey}»;
                  ${actor.name} получает его перманентно на Ступени «${finalRank}» (Дружественный для дальнейшего Продвижения).</div>
                </div>`
              }, game.settings.get("core", "rollMode")));
            } else {
              // Временная кража на сутки — исходные Ступени ОБЕИХ сторон
              // запоминаются для честного отката (hooks.mjs::updateWorldTime).
              const victimRank = targetActor.system.skills[skillKey]?.rank;
              const myRank = actor.system.skills?.[skillKey]?.rank ?? "untrained";
              await targetActor.update({ [`system.skills.${skillKey}.rank`]: "untrained" });
              await actor.update({ [`system.skills.${skillKey}.rank`]: victimRank });
              const nextList = [
                ...list.filter(r => r.key !== recKey),
                { key: recKey, victimUuid: targetActor.uuid, skillKey, streak, lastDay: today,
                  expiresAt: worldTime + DAY, bearerPrevRank: myRank, victimPrevRank: victimRank }
              ];
              await actor.setFlag("warhammer-dbc", listFlag, nextList);
              await ChatMessage.create(ChatMessage.applyRollMode({
                speaker,
                content: `<div class="wh-roll-result">
                  <div class="roll-header">Пожиратель Знаний — ${actor.name}</div>
                  <div class="roll-threshold">Навык «${skillKey}» (${victimRank}) украден у ${targetActor.name} на сутки — серия ${streak}/9.</div>
                </div>`
              }, game.settings.get("core", "rollMode")));
            }
          }
        },
        cancel: { label: "Отмена" }
      },
      default: "go"
    }).render(true);
  }
}
